{
  "actions": [
    {
      "title": "CreateProfile",
      "description": "Add a new customer profile with email, phone number, name, and custom properties.",
      "type": "action",
      "documentation": "https://developers.klaviyo.com/en/reference/api_overview",
      "endpointUrl": "/profiles",
      "apiBaseUrl": "https://a.klaviyo.com/api",
      "method": "POST",
      "sampleResponse": {
        "id": "profile_id",
        "email": "user@example.com",
        "first_name": "John",
        "last_name": "Doe",
        "phone_number": "+1234567890",
        "properties": {
          "custom_key": "custom_value"
        }
      },
      "inputSchema": {
        "type": "object",
        "description": "Input schema for creating a customer profile.",
        "properties": {
          "email": {
            "type": "string",
            "description": "Email address of the profile (required)."
          },
          "phone_number": {
            "type": "string",
            "description": "Phone number of the profile (optional)."
          },
          "first_name": {
            "type": "string",
            "description": "First name of the customer (optional)."
          },
          "last_name": {
            "type": "string",
            "description": "Last name of the customer (optional)."
          },
          "properties": {
            "type": "object",
            "description": "A key-value object of custom attributes (optional)."
          }
        },
        "required": [
          "email"
        ]
      },
      "outputType": {
        "outputType": "object"
      }
    },
    {
      "title": "GetProfile",
      "description": "Retrieve a specific customer profile by its ID.",
      "type": "action",
      "documentation": "https://developers.klaviyo.com/en/reference/api_overview",
      "endpointUrl": "/profiles/{id}",
      "apiBaseUrl": "https://a.klaviyo.com/api",
      "method": "GET",
      "sampleResponse": {
        "id": "profile_id",
        "email": "user@example.com",
        "first_name": "John",
        "last_name": "Doe",
        "phone_number": "+1234567890",
        "properties": {
          "custom_key": "custom_value"
        }
      },
      "inputSchema": {
        "type": "object",
        "description": "Input schema for retrieving a specific profile.",
        "properties": {
          "id": {
            "type": "string",
            "description": "Unique identifier of the customer profile."
          }
        },
        "required": [
          "id"
        ]
      },
      "outputType": {
        "outputType": "object"
      }
    },
    {
      "title": "UpdateProfile",
      "description": "Update attributes or custom properties of an existing customer profile.",
      "type": "action",
      "documentation": "https://developers.klaviyo.com/en/reference/api_overview",
      "endpointUrl": "/profiles/{id}",
      "apiBaseUrl": "https://a.klaviyo.com/api",
      "method": "PATCH",
      "sampleResponse": {
        "id": "profile_id",
        "email": "user@example.com",
        "first_name": "Jane",
        "last_name": "Doe",
        "phone_number": "+1234567890",
        "properties": {
          "custom_key": "updated_value"
        }
      },
      "inputSchema": {
        "type": "object",
        "description": "Input schema for updating a customer profile.",
        "properties": {
          "id": {
            "type": "string",
            "description": "Unique identifier of the customer profile to update."
          },
          "email": {
            "type": "string",
            "description": "Updated email address (optional)."
          },
          "phone_number": {
            "type": "string",
            "description": "Updated phone number (optional)."
          },
          "first_name": {
            "type": "string",
            "description": "Updated first name (optional)."
          },
          "last_name": {
            "type": "string",
            "description": "Updated last name (optional)."
          },
          "properties": {
            "type": "object",
            "description": "Updated custom attributes (optional)."
          }
        },
        "required": [
          "id"
        ]
      },
      "outputType": {
        "outputType": "object"
      }
    },
    {
      "title": "FindProfiles",
      "description": "Search for customer profiles based on query parameters such as email or phone number.",
      "type": "action",
      "documentation": "https://developers.klaviyo.com/en/reference/api_overview",
      "endpointUrl": "/profiles",
      "apiBaseUrl": "https://a.klaviyo.com/api",
      "method": "GET",
      "sampleResponse": {
        "profiles": [
          {
            "id": "profile_id_1",
            "email": "user1@example.com"
          },
          {
            "id": "profile_id_2",
            "email": "user2@example.com"
          }
        ]
      },
      "inputSchema": {
        "type": "object",
        "description": "Input schema for searching customer profiles.",
        "properties": {
          "query": {
            "type": "string",
            "description": "Search query to filter profiles by email, phone number, etc."
          }
        }
      },
      "outputType": {
        "outputType": "array",
        "arrayPropertyValue": "profiles"
      }
    },
    {
      "title": "DeleteProfile",
      "description": "Remove a customer profile from Klaviyo using its unique ID.",
      "type": "action",
      "documentation": "https://developers.klaviyo.com/en/reference/api_overview",
      "endpointUrl": "/profiles/{id}",
      "apiBaseUrl": "https://a.klaviyo.com/api",
      "method": "DELETE",
      "sampleResponse": {
        "status": "deleted"
      },
      "inputSchema": {
        "type": "object",
        "description": "Input schema for deleting a customer profile.",
        "properties": {
          "id": {
            "type": "string",
            "description": "Unique identifier of the customer profile to delete."
          }
        },
        "required": [
          "id"
        ]
      },
      "outputType": {
        "outputType": "object"
      }
    },
    {
      "title": "CreateList",
      "description": "Create a new static list for organizing customer profiles.",
      "type": "action",
      "documentation": "https://developers.klaviyo.com/en/reference/api_overview",
      "endpointUrl": "/lists",
      "apiBaseUrl": "https://a.klaviyo.com/api",
      "method": "POST",
      "sampleResponse": {
        "id": "list_id",
        "name": "My Subscriber List",
        "description": "A list of subscribers."
      },
      "inputSchema": {
        "type": "object",
        "description": "Input schema for creating a new list.",
        "properties": {
          "name": {
            "type": "string",
            "description": "Name of the list."
          },
          "description": {
            "type": "string",
            "description": "Description of the list (optional)."
          }
        },
        "required": [
          "name"
        ]
      },
      "outputType": {
        "outputType": "object"
      }
    },
    {
      "title": "FindLists",
      "description": "Retrieve all available lists with their metadata; supports filtering via query.",
      "type": "action",
      "documentation": "https://developers.klaviyo.com/en/reference/api_overview",
      "endpointUrl": "/lists",
      "apiBaseUrl": "https://a.klaviyo.com/api",
      "method": "GET",
      "sampleResponse": {
        "lists": [
          {
            "id": "list_id",
            "name": "My Subscriber List"
          }
        ]
      },
      "inputSchema": {
        "type": "object",
        "description": "Input schema for searching available lists.",
        "properties": {
          "query": {
            "type": "string",
            "description": "Optional search query for filtering lists."
          }
        }
      },
      "outputType": {
        "outputType": "array",
        "arrayPropertyValue": "lists"
      }
    },
    {
      "title": "AddProfilesToList",
      "description": "Add one or more customer profile IDs to a specific list.",
      "type": "action",
      "documentation": "https://developers.klaviyo.com/en/reference/api_overview",
      "endpointUrl": "/lists/{id}/relationships/profiles",
      "apiBaseUrl": "https://a.klaviyo.com/api",
      "method": "POST",
      "sampleResponse": {
        "status": "profiles added"
      },
      "inputSchema": {
        "type": "object",
        "description": "Input schema for adding profiles to a list.",
        "properties": {
          "id": {
            "type": "string",
            "description": "Unique identifier of the target list."
          },
          "profile_ids": {
            "type": "array",
            "description": "Array of customer profile IDs to be added.",
            "items": {
              "type": "string"
            }
          }
        },
        "required": [
          "id",
          "profile_ids"
        ]
      },
      "outputType": {
        "outputType": "object"
      }
    },
    {
      "title": "RemoveProfilesFromList",
      "description": "Remove one or more customer profile IDs from a specific list.",
      "type": "action",
      "documentation": "https://developers.klaviyo.com/en/reference/api_overview",
      "endpointUrl": "/lists/{id}/relationships/profiles",
      "apiBaseUrl": "https://a.klaviyo.com/api",
      "method": "DELETE",
      "sampleResponse": {
        "status": "profiles removed"
      },
      "inputSchema": {
        "type": "object",
        "description": "Input schema for removing profiles from a list.",
        "properties": {
          "id": {
            "type": "string",
            "description": "Unique identifier of the target list."
          },
          "profile_ids": {
            "type": "array",
            "description": "Array of customer profile IDs to be removed.",
            "items": {
              "type": "string"
            }
          }
        },
        "required": [
          "id",
          "profile_ids"
        ]
      },
      "outputType": {
        "outputType": "object"
      }
    },
    {
      "title": "CreateCampaign",
      "description": "Create a new email campaign with specified details including name, subject, template, and target list IDs.",
      "type": "action",
      "documentation": "https://developers.klaviyo.com/en/reference/api_overview",
      "endpointUrl": "/campaigns",
      "apiBaseUrl": "https://a.klaviyo.com/api",
      "method": "POST",
      "sampleResponse": {
        "id": "campaign_id",
        "name": "Winter Sale Campaign",
        "subject": "Big Discounts This Winter"
      },
      "inputSchema": {
        "type": "object",
        "description": "Input schema for creating a new campaign.",
        "properties": {
          "name": {
            "type": "string",
            "description": "Name of the campaign."
          },
          "subject": {
            "type": "string",
            "description": "Subject line of the email campaign."
          },
          "template_id": {
            "type": "string",
            "description": "Identifier for the email template."
          },
          "list_ids": {
            "type": "array",
            "description": "Array of target list IDs for the campaign.",
            "items": {
              "type": "string"
            }
          }
        },
        "required": [
          "name",
          "subject",
          "template_id",
          "list_ids"
        ]
      },
      "outputType": {
        "outputType": "object"
      }
    },
    {
      "title": "FindCampaigns",
      "description": "Retrieve and search through email campaigns based on filtering parameters.",
      "type": "action",
      "documentation": "https://developers.klaviyo.com/en/reference/api_overview",
      "endpointUrl": "/campaigns",
      "apiBaseUrl": "https://a.klaviyo.com/api",
      "method": "GET",
      "sampleResponse": {
        "campaigns": [
          {
            "id": "campaign_id",
            "name": "Winter Sale Campaign"
          }
        ]
      },
      "inputSchema": {
        "type": "object",
        "description": "Input schema for finding email campaigns.",
        "properties": {
          "query": {
            "type": "string",
            "description": "Optional search filter for campaigns."
          }
        }
      },
      "outputType": {
        "outputType": "array",
        "arrayPropertyValue": "campaigns"
      }
    },
    {
      "title": "SendCampaign",
      "description": "Trigger sending of an email campaign to its target audience.",
      "type": "action",
      "documentation": "https://developers.klaviyo.com/en/reference/api_overview",
      "endpointUrl": "/campaigns/{id}/send",
      "apiBaseUrl": "https://a.klaviyo.com/api",
      "method": "POST",
      "sampleResponse": {
        "status": "sent",
        "sent_at": "2024-10-15T12:00:00Z"
      },
      "inputSchema": {
        "type": "object",
        "description": "Input schema for sending an email campaign.",
        "properties": {
          "id": {
            "type": "string",
            "description": "Unique identifier of the campaign to send."
          },
          "send_time": {
            "type": "string",
            "description": "Optional scheduled send time in ISO 8601 format."
          }
        },
        "required": [
          "id"
        ]
      },
      "outputType": {
        "outputType": "object"
      }
    },
    {
      "title": "CreateEvent",
      "description": "Track a custom event for a customer profile, such as a purchase or page view.",
      "type": "action",
      "documentation": "https://developers.klaviyo.com/en/reference/api_overview",
      "endpointUrl": "/events",
      "apiBaseUrl": "https://a.klaviyo.com/api",
      "method": "POST",
      "sampleResponse": {
        "id": "event_id",
        "metric_name": "Purchase",
        "timestamp": "2024-10-15T12:00:00Z"
      },
      "inputSchema": {
        "type": "object",
        "description": "Input schema for tracking a custom event.",
        "properties": {
          "profile_id": {
            "type": "string",
            "description": "Unique identifier of the customer profile. Either profile_id or profile_email is required."
          },
          "profile_email": {
            "type": "string",
            "description": "Email address of the customer profile (as an alternative to profile_id)."
          },
          "metric_name": {
            "type": "string",
            "description": "Name of the event or metric to be tracked."
          },
          "properties": {
            "type": "object",
            "description": "Additional event properties in key-value format (optional)."
          },
          "time": {
            "type": "string",
            "description": "Timestamp of the event in ISO 8601 format (optional)."
          }
        },
        "required": [
          "metric_name"
        ]
      },
      "outputType": {
        "outputType": "object"
      }
    }
  ],
  "authentication": {
    "type": "apiKey",
    "authUrl": "https://developers.klaviyo.com/en/reference/api_overview#authentication",
    "tokenUrl": "",
    "profileInfoUrl": "https://a.klaviyo.com/api/profiles/me"
  },
  "serviceJson": {
    "name": "appmixer.klaviyo",
    "label": "Klaviyo",
    "category": "applications",
    "description": "Klaviyo integration for managing customer profiles, lists, campaigns, and event tracking.",
    "version": "1.0.0",
    "icon": "https://example.com/klaviyo-icon.svg"
  }
}
